// Pinned Anon-RPC specifiers: the app answers the harness's two startup reads (workerHash, workerResolvers) itself,
// so starting Anon-RPC makes no direct, non-anonymous request at all (the old way read a public node directly).
//
// Better than a plain pin (Atmos and Navik pin by hand and never notice when a network ships a new worker):
// - pins.json is generated by `bun run pin` (scripts/pin.ts), which also saves a hash-checked copy of each worker
//   bundle to public/w/<hash>.js, listed first so no third-party CDN sees users at startup;
// - once a network is up, the app reads the live specifier THROUGH the mixnet and, if the network has moved on,
//   stores the new pin for next time (still anonymous);
// - if a pin is so stale the worker can't boot, that one network boots with a live read instead (shown as
//   "startup read" in the traffic share), so availability never depends on the pin.
import pins from "./pins.json";
import type { NetworkName } from "./config";
import { SEL_HASH, SEL_RESOLVERS, decodeStrings, encodeStrings, withOwnCopy } from "./resolvers";

export interface Pin { workerHash: string; resolvers: string[] }
type PinFile = Record<string, Pin & { address: string; selfHosted: boolean }>;
const FILE = pins as PinFile;
const KEY = (n: NetworkName) => `bp.pin.${n}`;

const stored = (n: NetworkName): Pin | undefined => {
  try { const v = JSON.parse(localStorage.getItem(KEY(n)) ?? "null"); return v?.workerHash && Array.isArray(v.resolvers) ? v : undefined; } catch { return undefined; }
};

/** The pin to boot with: a fresher one learned through the mixnet if we have it, else the built-in one. */
export function currentPin(n: NetworkName): (Pin & { own?: string }) | undefined {
  const built = FILE[n];
  const p = stored(n) ?? built;
  if (!p) return undefined;
  // Our own copy only exists for the built-in hash (the file is named after it).
  const own = built?.selfHosted && p.workerHash === built.workerHash ? `w/${built.workerHash.slice(2)}.js` : undefined;
  return { ...p, own };
}

/** A provider for the harness that answers the two specifier reads from the pin and refuses anything else, so a
 *  pinned boot can never make a direct request. */
export function pinnedProvider(n: NetworkName, address: string, siteBase: string) {
  const p = currentPin(n);
  return {
    request: async ({ method, params }: { method: string; params?: unknown[] }) => {
      const call = (params?.[0] ?? {}) as { to?: string; data?: string };
      if (p && method === "eth_call" && call.to?.toLowerCase() === address.toLowerCase()) {
        if (call.data?.startsWith(SEL_HASH)) return p.workerHash;
        if (call.data?.startsWith(SEL_RESOLVERS)) return encodeStrings(withOwnCopy(p.resolvers, p.own && new URL(p.own, siteBase).toString()));
      }
      throw new Error(`pinned specifier: refusing a direct ${method} (no pin for ${n})`);
    },
  };
}

export const hasPin = (n: NetworkName) => !!currentPin(n);

/** Compare the pin with the live specifier, read through the mixnet. Saves a newer pin for the next start. */
export async function refreshPin(n: NetworkName, address: string, ethCall: (to: string, data: string) => Promise<string>): Promise<"same" | "updated"> {
  const p = currentPin(n);
  const hash = await ethCall(address, SEL_HASH);
  if (p && hash.toLowerCase() === p.workerHash.toLowerCase()) return "same";
  const resolvers = decodeStrings(await ethCall(address, SEL_RESOLVERS));
  try { localStorage.setItem(KEY(n), JSON.stringify({ workerHash: hash, resolvers })); } catch {}
  return "updated";
}

/** A pin that failed to boot: forget the stored override (if any) so the next start doesn't repeat it. */
export function forgetPin(n: NetworkName) { try { localStorage.removeItem(KEY(n)); } catch {} }
